import {mapMarkup,gearDetails} from './dependency-map.js';
import {equipmentPreview} from './equipment-previews.js';
import {idlePose,renderIdle,preloadIdleAssets} from './idle-animation.js';
import {walkingPose,renderWalking} from './walking-animation.js';
import {CHARACTERS,characterArt,buildingArt} from './characters.js';
import {playerStore,validateName,SAVE_KEY} from './player-store.js';
import {ECONOMY,EQUIPMENT,MATERIALS,catalogItem} from './equipment-catalog.js';
import {TUTORIAL_STAGES,currentTutorial,tutorialEvent,replayTutorial} from './tutorial.js';
import {PLACES,placePoint,movePlayer,nearestPlace,routeTo,walkable} from './town-model.js';
import {experiments,eligibility,equipmentUnlocks} from './experiment-definitions.js';
import {requirementDetails} from './progression-ui.js';
import {purchase,claimTrialGrant,applyReward,launchExperiment} from './progression.js';
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
let player=null,character=null,replacing=false,keys=new Set(),route=[],target=null,panelKind=null,last=0,moved=0,moveReported=false,saveTimer=null,portraitFacing='',motion=0,isWalking=false,idleElapsed=0,townIdleElapsed=0,guideCharacterId=null,started=false,protectedProfile=false;
const safe=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
function error(e){$('save-status').textContent=e.message||String(e);}
async function mutate(fn){try{const result=await playerStore.transact(p=>{if(player&&p.profileId!==player.profileId)throw Error('The local profile changed in another tab. Return to town and retry.');if(player)p.position={...player.position};return fn(p);});const live=player?.position;player=result.player;if(live)player.position=live;renderHud();return result.result;}catch(e){error(e);return null;}}
async function event(id){return mutate(p=>tutorialEvent(p,id));}
function onboarding(replace=false){replacing=replace;character=null;$('onboarding').hidden=false;$('game').hidden=true;$('start-adventure').disabled=true;$('player-name').value='';$('name-error').textContent='';$('cancel-new-game').hidden=!player;$('character-options').innerHTML=CHARACTERS.map(c=>`<button type="button" class="character-choice" data-character-choice="${c.id}" aria-pressed="false" aria-label="${safe(c.description)}">${characterArt(c.id)}<strong>${c.name}</strong><small>${safe(c.description)}</small></button>`).join('');}
function renderHud(){if(!player)return;$('player-summary').textContent=player.name;$('credits-button').textContent=`${player.currency} ${ECONOMY.name}`;$('save-status').textContent=playerStore.warning;const t=currentTutorial(player),card=$('tutorial-card');card.innerHTML=t?`<p>Welcome, ${safe(player.name)}.</p><span class="progress-badge">Tutorial ${player.tutorial.stage+1} / ${TUTORIAL_STAGES.length}</span><h2>${t.title}</h2><p>${t.text}</p><ul class="tutorial-checks">${t.requires.map(r=>`<li class="${player.tutorial.flags.includes(r)?'done':''}">${player.tutorial.flags.includes(r)?'✓':'○'} ${safe(r.replaceAll('-',' '))}</li>`).join('')}</ul>`:`<h2>Your town, your laboratory.</h2><p>${safe(player.name)}, explore equipment branches in the map or return to your laboratory. Replay the introduction from Options whenever you like.</p>`;drawObjective();}
function drawObjective(){if(!player)return;const stage=currentTutorial(player)?.id;let id;if(stage==='movement')id=!player.tutorial.flags.includes('welcome-sign')?'welcome-sign':'guide';else if(stage==='laboratory')id='laboratory';else if(stage==='progression')id='map';const p=PLACES.find(p=>p.id===id);$('objective-marker').innerHTML=p?`<circle class="objective-glow" cx="${placePoint(p).x}" cy="${placePoint(p).y}" r="29"/><path d="M${placePoint(p).x-8} ${placePoint(p).y-38}h16l-8 9Z" fill="#bb8b36"/>`:'';$('inventory-button').classList.toggle('objective-glow',stage==='inventory');$('credits-button').classList.toggle('objective-glow',stage==='currency');}
function startTown(){started=true;$('onboarding').hidden=true;$('game').hidden=false;$('protected-save').hidden=true;if(!walkable(player.position.x,player.position.y))player.position={x:600,y:570,facing:'front'};$('town-buildings').innerHTML=PLACES.filter(p=>p.art).map(p=>`<g data-place="${p.id}" tabindex="0" role="button" aria-label="Walk to ${p.name}">${buildingArt(p.art,p.x,p.y,p.w,p.h)}<text class="world-label" x="${p.door.x}" y="${p.door.y+24}" text-anchor="middle">${p.name}</text></g>`).join('');const guideId=player.characterId==='c01-5'?'c01-2':'c01-5';guideCharacterId=guideId;preloadIdleAssets([player.characterId,guideId]);const walkingImage=new Image();walkingImage.src='assets/world/walk-'+player.characterId+'.png';$('town-actors').innerHTML=`<g data-place="welcome-sign" tabindex="0" role="button" aria-label="Walk to welcome sign"><path d="M518 505V470" stroke="#7d725a" stroke-width="8"/><path d="M488 460H552V488H488Z" class="town-poi"/><text x="520" y="479" text-anchor="middle" font-size="10">CHEMTOPIA</text></g><g data-place="guide" tabindex="0" role="button" aria-label="Walk to town guide"><g id="guide-idle"></g><text class="world-label" x="567" y="391" text-anchor="middle">Guide</text></g><g data-place="map" tabindex="0" role="button" aria-label="Walk to progression map"><path d="M705 380V320M755 380V320" stroke="#756b54" stroke-width="7"/><rect class="town-poi" x="690" y="305" width="80" height="61"/><path d="M705 348L720 321 740 343 755 323" stroke="#4d8a80" stroke-width="3" fill="none"/><text class="world-label" x="730" y="298" text-anchor="middle">Lab map</text></g>`;portraitFacing='';motion=0;isWalking=false;idleElapsed=0;townIdleElapsed=0;renderPlayer();renderHud();if(!last)requestAnimationFrame(frame);if(new URL(location.href).searchParams.get('panel')==='map')showPanel('map');else if(new URL(location.href).searchParams.get('panel')==='shop')showPanel('shop');}
function renderPlayer(){
 if(!player)return;
 const reduced=motionPreference.matches,g=$('player'),p=player.position,pose=walkingPose(p.facing,motion,isWalking,reduced),key=player.characterId+':actor';
 g.setAttribute('transform',`translate(${p.x} ${p.y})`);
 if(portraitFacing!==key){
  g.innerHTML=`<ellipse cy="-2" rx="17" ry="6" fill="#425c4b35"/><g id="walking-art"></g><text y="-94" text-anchor="middle" class="world-label"></text>`;
  g.querySelector('text').textContent=player.name;portraitFacing=key;
 }
 if(isWalking)renderWalking($('walking-art'),player.characterId,pose);
 else renderIdle($('walking-art'),player.characterId,idlePose(player.characterId,idleElapsed,{direction:p.facing,reducedMotion:reduced,attention:panel.open||Boolean(keys.size||route.length)}),{x:-29,y:-87,width:58,height:87,facing:p.facing,scope:'player'});
 const guide=$('guide-idle');if(guide&&guideCharacterId)renderIdle(guide,guideCharacterId,idlePose(guideCharacterId,townIdleElapsed,{direction:'south',reducedMotion:reduced,attention:panel.open}),{x:540,y:388,width:56,height:84,facing:'front',scope:'guide'});
 g.classList.toggle('walking',isWalking);
 const nearby=nearestPlace(p),label=nearby?nearby.name:'Walk through Chemtopia';if($('nearby').textContent!==label)$('nearby').textContent=label;if($('interact-button').disabled!==!nearby)$('interact-button').disabled=!nearby;
}

async function persistPosition(){if(!player)return;await mutate(()=>{});}
function schedulePosition(){clearTimeout(saveTimer);saveTimer=setTimeout(persistPosition,450);}
function goTo(place){const point=placePoint(place);route=routeTo(player.position,point);target=place.id;if(!route.length&&nearestPlace(player.position)?.id===place.id)interact(place);$('destination-marker').innerHTML=`<circle cx="${point.x}" cy="${point.y}" r="8" fill="none" stroke="#af853e" stroke-width="3"/>`;}
async function interact(place=nearestPlace(player.position)){if(!place)return;$('town-message').textContent='';if(place.id==='welcome-sign'){await event('welcome-sign');showDialogue('Welcome to Chemtopia',`${player.name}, this square connects your laboratory, the equipment shop and the progression map. Click a destination or use movement keys, then E / Interact nearby.`);}else if(place.id==='guide'){await event('guide');showDialogue('Town guide',`Welcome, ${player.name}. Your laboratory starts with only a beaker, basin and heater. Inspect your inventory, then try recovering salt. Equipment opens new branches; you will not need to follow a fixed topic order.`);}else if(place.id==='laboratory'){await event('enter-lab');location.href='laboratory.html?adventure=1';}else if(place.id==='shop')showPanel('shop');else if(place.id==='map')showPanel('map');else if(place.id==='home')showPanel('options');else showDialogue('Science school',`${player.name}, this is a future mission location. Missions and their rewards have not been designed yet. Your current equipment branches are available through the shop and map.`);}
function frame(time){
 if(!player||$('game').hidden){last=0;return;}
 const dt=Math.min(.05,(time-last)/1000||.016);last=time;
 let dx=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0),dy=(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0);
 if(!dx&&!dy){
  // Consume reached route points in this frame, preserving gait across tiles.
  while(route.length){
   const waypoint=route[0],distance=Math.hypot(waypoint.x-player.position.x,waypoint.y-player.position.y);
   if(distance>=5){dx=waypoint.x-player.position.x;dy=waypoint.y-player.position.y;break;}
   route.shift();
   if(!route.length&&target){const place=PLACES.find(p=>p.id===target);target=null;if(place&&Math.hypot(placePoint(place).x-player.position.x,placePoint(place).y-player.position.y)<90)interact(place);}
  }
 }
 isWalking=false;
 if(!panel.open&&(dx||dy)){
  const before=player.position;const travelTime=!keys.size&&route.length?Math.min(dt,Math.hypot(dx,dy)/180):dt;player.position=movePlayer(before,dx,dy,travelTime);
  const distance=Math.hypot(before.x-player.position.x,before.y-player.position.y);moved+=distance;
  if(distance){isWalking=true;motion+=distance;schedulePosition();if(moved>40&&!moveReported){moveReported=true;event('move');}}
 }
 if(!isWalking){motion=0;if(!document.hidden)idleElapsed+=dt*1000;}else idleElapsed=0;
 if(!document.hidden)townIdleElapsed+=dt*1000;
 renderPlayer();requestAnimationFrame(frame);
}

const panel=$('panel');function openPanel(title,html,kind){panelKind=kind;$('panel-title').textContent=title;$('panel-content').innerHTML=html;keys.clear();if(!panel.open)panel.showModal();}
function showDialogue(title,text){openPanel(title,`<p>${safe(text)}</p><button data-action="close" class="primary">Continue</button>`,'dialogue');}
function inventoryHtml(){return `<p>Equipment stays owned after use. Consumables supply one attempt at a time. The laboratory drawer holds the apparatus used in the current experiment.</p><h3>Reusable equipment</h3><div class="inventory-grid">${Object.entries(player.equipment).filter(([,n])=>n>0).map(([id,n])=>`<button class="item-card" data-inspect-equipment="${id}"><strong>${safe(catalogItem(id)?.name||id)} × ${n}</strong><small>Reusable equipment · inspect</small></button>`).join('')}</div><h3>Consumable materials</h3><div class="inventory-grid">${Object.entries(player.materials).filter(([,n])=>n>0).map(([id,n])=>`<button class="item-card" data-inspect-material="${id}"><strong>${safe(catalogItem(id)?.name||id)} × ${n}</strong><small>Consumable experiment supply · inspect</small></button>`).join('')||'<p>No unused supplies. Visit the supply counter in the shop.</p>'}</div><div id="item-detail"></div>`;}
async function showPanel(kind){if(!player)return;if(kind==='inventory'){openPanel('Your inventory',inventoryHtml(),kind);await event('inventory-open');}else if(kind==='currency'){openPanel(ECONOMY.name,`<p>${safe(player.name)}, you have <strong>${player.currency} ${ECONOMY.name}</strong>.</p><p>Spend credits on reusable apparatus in the equipment shop. Future missions can award credits or equipment. Mission rewards are not configured yet; the shop has a clearly labelled testing allowance.</p><p>Equipment prices and this currency name are provisional. Your balance is always in the town header.</p><button class="primary" data-action="currency-read">Got it</button>`,kind);}else if(kind==='options'){openPanel('Your adventure',`<p>Player: <strong>${safe(player.name)}</strong> · ${safe(CHARACTERS.find(c=>c.id===player.characterId).name)}</p><p>Progress is stored locally in this browser. Returning resumes your town position, tutorial and inventory; laboratory attempts themselves restart.</p><div class="panel-actions"><button data-action="replay">Replay tutorial</button><a href="idle-preview.html">Preview character idles</a><button data-action="new-game" class="danger">New Game</button><button data-action="close">Return to town</button></div>`,kind);}else if(kind==='shop')renderShop();else if(kind==='map'){renderMap();await event('open-map');}}
function renderShop(){openPanel('Equipment & supplies',`<p>${player.currency} ${ECONOMY.name}. All prices are configurable trial values.</p><div class="panel-actions"><button data-action="grant">Claim one-time testing allowance (${ECONOMY.trialGrant})</button><button data-action="map">View equipment branches</button></div><p class="disabled-note">The allowance is a testing foundation, not a permanent mission reward. Basic supplies are accessible here to keep practice resumable.</p><h3>Reusable equipment</h3><div class="shop-grid">${Object.values(EQUIPMENT).map(i=>`<article class="item-card equipment-shop-card">${equipmentPreview(i.id)}<strong>${i.name}</strong><p>${i.description}</p><small>Used by: ${equipmentUnlocks(player,i.id).map(e=>e.name).slice(0,3).join(', ')||'Your existing laboratory kit'}</small><small>Owned: ${player.equipment[i.id]||0} · ${i.price===undefined?'Reward only':i.price+' '+ECONOMY.name}</small><button data-buy="${i.id}" ${i.price===undefined?'disabled':''}>Buy one</button></article>`).join('')}</div><h3>Consumable experiment supplies</h3><div class="shop-grid">${Object.values(MATERIALS).map(i=>`<article class="item-card"><strong>${i.name}</strong><p>${i.description}</p><small>Owned: ${player.materials[i.id]||0} · ${i.price} ${ECONOMY.name}</small><button data-buy="${i.id}">Obtain one supply</button></article>`).join('')}</div><p id="purchase-note" role="status"></p>`,'shop');}
function requirementsHtml(e){const r=eligibility(player,e.id),attempt=player.attempts[e.id];return requirementDetails(player,e)+`<div class="panel-actions"><button class="primary" data-launch="${e.id}" ${r.available?'':'disabled'}>${r.available?'Start experiment':'Requirements not met'}</button>${attempt?.status==='active'?`<a href="${e.file}?adventure=1">Resume reserved attempt</a>`:''}<button data-action="shop">Obtain equipment / supplies</button></div><p class="disabled-note">One set of listed supplies is reserved for an attempt. Restarting that attempt uses the same reservation; starting another reserves another supply.</p>`;}
let selectedExperiment='evaporation',mapScale=innerWidth<800?2:1,mapOffset={x:0,y:0},mapDrag=null,mapNodes=[],mapBounds={width:950,height:620};
let mapFocused=true;
function renderMap(){
 const result=mapMarkup(player,selectedExperiment,mapFocused);mapNodes=result.layout.nodes;
 mapBounds={width:Math.max(350,...mapNodes.map(n=>n.x+190)),height:Math.max(250,...mapNodes.map(n=>n.y+90))};
 const selector=`<div class="map-accessible-list"><label for="map-experiment-select">Choose an experiment</label><select id="map-experiment-select">${experiments.map(e=>`<option value="${e.id}" ${e.id===selectedExperiment?'selected':''}>${e.name} — ${eligibility(player,e.id).label}</option>`).join('')}</select></div>`;
 const board=result.html.replace('<svg id="progression-map"',selector+'<svg id="progression-map"');
 openPanel('Laboratory progression map',`<div class="network-workspace"><div class="network-board">${board}</div><section id="experiment-detail" class="network-inspector" aria-live="polite">${requirementsHtml(experiments.find(e=>e.id===selectedExperiment)||experiments[0])}</section></div>`,'map');
 mapScale=Math.min(950/mapBounds.width,620/mapBounds.height);mapOffset={x:0,y:0};updateMapCamera();
}
function focusMapNode(id){const n=mapNodes.find(n=>n.id===id);if(n){const x=n.x*mapScale+mapOffset.x,y=n.y*mapScale+mapOffset.y;if(x<20||x+165*mapScale>930)mapOffset.x=40-n.x*mapScale;if(y<20||y+66*mapScale>600)mapOffset.y=100-n.y*mapScale;}updateMapCamera();}
function updateMapCamera(){const c=$('map-camera');if(c)c.setAttribute('transform',`translate(${mapOffset.x} ${mapOffset.y}) scale(${mapScale})`);}
async function selectExperiment(id){selectedExperiment=id;renderMap();focusMapNode(id);const e=experiments.find(e=>e.id===id);if(!e)return;$('experiment-detail').innerHTML=requirementsHtml(e);await event('view-requirements');if(!eligibility(player,id).available||experiments.every(e=>eligibility(player,e.id).available))await event('inspect-locked');}
$('panel-content').addEventListener('click',async e=>{try{const b=e.target.closest('button,[data-experiment],[data-network-gear]');if(!b)return;if(b.dataset.networkGear){$('experiment-detail').innerHTML=gearDetails(player,b.dataset.networkGear);}else if(b.dataset.inspectEquipment||b.dataset.inspectMaterial){const equipment=Boolean(b.dataset.inspectEquipment),id=b.dataset.inspectEquipment||b.dataset.inspectMaterial,item=catalogItem(id);$('item-detail').innerHTML=`<div class="item-description"><h3>${safe(item?.name||id)}</h3><p>${safe(item?.description||'Unrecognised saved item; kept for compatibility.')}</p><p>${equipment?'Reusable equipment stays owned.':'Consumable supplies are used to start attempts.'}</p><small>Source: ${safe(item?.source||'Saved inventory')}</small></div>`;await event(equipment?'inspect-equipment':'inspect-material');}else if(b.dataset.buy){const result=await mutate(p=>purchase(p,b.dataset.buy));renderShop();$('purchase-note').textContent=result?.message||$('save-status').textContent;}else if(b.dataset.launch){await launchExperiment(playerStore,b.dataset.launch);location.href=experiments.find(x=>x.id===b.dataset.launch).file+'?adventure=1';}else if(b.dataset.experiment)await selectExperiment(b.dataset.experiment);else if(b.dataset.mapZoom){mapScale=Math.max(.35,Math.min(3,mapScale*Number(b.dataset.mapZoom)));updateMapCamera();}else if(b.dataset.mapPan){const d={left:[100,0],right:[-100,0],up:[0,100],down:[0,-100]}[b.dataset.mapPan];mapOffset.x+=d[0];mapOffset.y+=d[1];updateMapCamera();}else{const action=b.dataset.action;if(action==='map-network'){mapFocused=!mapFocused;renderMap();}else if(action==='close')panel.close();else if(action==='currency-read'){await event('currency-read');panel.close();}else if(action==='inventory'||action==='map'||action==='shop')showPanel(action);else if(action==='grant'){const result=await mutate(claimTrialGrant);renderShop();$('purchase-note').textContent=result?.message||'Could not claim allowance.';}else if(action==='replay'){await mutate(replayTutorial);moveReported=false;moved=0;panel.close();}else if(action==='new-game'){if(confirm('Start a new adventure and replace this local profile? Your current save will be archived locally.')){panel.close();onboarding(true);}}else if(action==='map-reset'){mapScale=Math.min(950/mapBounds.width,620/mapBounds.height);mapOffset={x:0,y:0};updateMapCamera();}}}catch(err){error(err);}});
$('panel-content').addEventListener('change',e=>{if(e.target.id==='map-experiment-select')selectExperiment(e.target.value);});
$('panel-content').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.networkGear){e.preventDefault();$('experiment-detail').innerHTML=gearDetails(player,e.target.dataset.networkGear);}else if(e.key==='Enter'&&e.target.dataset.experiment){e.preventDefault();selectExperiment(e.target.dataset.experiment);}});
$('panel-content').addEventListener('pointerdown',e=>{if(!e.target.closest('#progression-map')||e.target.closest('[data-experiment],[data-network-gear]'))return;mapDrag={x:e.clientX,y:e.clientY,start:{...mapOffset}};e.target.setPointerCapture(e.pointerId);});
$('panel-content').addEventListener('pointermove',e=>{if(!mapDrag)return;const svg=$('progression-map'),r=svg.getBoundingClientRect(),scale=svg.viewBox.baseVal.width/r.width;mapOffset={x:mapDrag.start.x+(e.clientX-mapDrag.x)*scale,y:mapDrag.start.y+(e.clientY-mapDrag.y)*scale};updateMapCamera();});
$('panel-content').addEventListener('pointerup',()=>mapDrag=null);$('panel-content').addEventListener('pointercancel',()=>mapDrag=null);
$('close-panel').addEventListener('click',()=>panel.close());panel.addEventListener('close',()=>{panelKind=null;mapDrag=null;});
$('character-options').addEventListener('click',e=>{const b=e.target.closest('[data-character-choice]');if(!b)return;character=b.dataset.characterChoice;for(const el of $('character-options').children)el.setAttribute('aria-pressed',String(el===b));validateForm();});
function validateForm(){const r=validateName($('player-name').value);$('name-error').textContent=$('player-name').value&&!r.ok?r.message:'';$('start-adventure').disabled=!character||!r.ok;}
$('player-name').addEventListener('input',validateForm);$('new-player-form').addEventListener('submit',e=>{e.preventDefault();if(protectedProfile&&!confirm('Replace the protected profile? The original data will be archived locally.'))return;try{player=playerStore.start($('player-name').value,character,{confirmed:replacing});route=[];target=null;moveReported=false;moved=0;protectedProfile=false;startTown();}catch(e){$('name-error').textContent=e.message;}});
$('cancel-new-game').addEventListener('click',()=>startTown());$('restore-backup').addEventListener('click',()=>{try{player=playerStore.restoreBackup();protectedProfile=false;startTown();}catch(e){$('protected-save').textContent=e.message;}});
$('inventory-button').addEventListener('click',()=>showPanel('inventory'));$('map-button').addEventListener('click',()=>showPanel('map'));$('credits-button').addEventListener('click',()=>showPanel('currency'));$('options-button').addEventListener('click',()=>showPanel('options'));$('interact-button').addEventListener('click',()=>interact());
$('town').addEventListener('click',e=>{if(!player||panel.open)return;const place=PLACES.find(p=>p.id===e.target.closest('[data-place]')?.dataset.place);if(place){goTo(place);return;}const p=new DOMPoint(e.clientX,e.clientY).matrixTransform($('town').getScreenCTM().inverse());route=routeTo(player.position,p);target=null;$('destination-marker').innerHTML=route.length?`<circle cx="${route.at(-1).x}" cy="${route.at(-1).y}" r="7" fill="none" stroke="#af853e" stroke-width="2"/>`:'';});
$('town').addEventListener('keydown',e=>{const p=e.target.closest('[data-place]');if(p&&e.key==='Enter'){e.preventDefault();goTo(PLACES.find(x=>x.id===p.dataset.place));}});
window.addEventListener('keydown',e=>{if(!player||panel.open||e.target.closest('input,textarea,select')||$('game').hidden)return;const key=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(key)){e.preventDefault();keys.add(key);route=[];target=null;}else if(key==='e'){e.preventDefault();interact();}else if(key==='i')showPanel('inventory');else if(key==='m')showPanel('map');});window.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',()=>keys.clear());
for(const b of document.querySelectorAll('[data-direction]')){const key={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[b.dataset.direction];b.addEventListener('pointerdown',e=>{e.preventDefault();route=[];target=null;keys.add(key);b.setPointerCapture(e.pointerId);});for(const name of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(name,()=>keys.delete(key));}
window.addEventListener('storage',e=>{if(e.key===SAVE_KEY){const l=playerStore.load();if(l.status==='ready'){const changed=player?.profileId!==l.player.profileId;player=l.player;if(changed){panel.close();keys.clear();route=[];target=null;startTown();}else renderHud();if(panelKind==='shop')renderShop();if(panelKind==='map')renderMap();}else{player=null;onboarding();}}});window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);if(player&&!$('game').hidden){try{playerStore.update(p=>{if(p.profileId!==player.profileId)throw Error('Profile changed');p.position={...player.position};});}catch{}}});
const loaded=playerStore.load();if(loaded.status==='ready'){player=loaded.player;startTown();}else{onboarding(loaded.status==='protected');if(loaded.status==='protected'){$('protected-save').hidden=false;$('protected-save').textContent=loaded.error+' Your original data is protected. Starting another adventure will ask for confirmation.';$('restore-backup').hidden=!loaded.backup;protectedProfile=true;}}
